# YUVAA Saarthi — FastAPI Dependencies
# Reference: PRD §3.1 (Auth) & Execution Plan Phase 2
#
# BUG-003 FIX: Now validates HS256 JWT tokens generated by auth.py.
# Falls back to Supabase JWT validation for real Supabase tokens.
# Dev-bypass (DEV_BYPASS_AUTH=true) still works for local testing.

import os
import logging
from fastapi import Depends, HTTPException, Header, status
from typing import Optional
from app.supabase_client import supabase
from app.config import settings

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Typed holder for the authenticated user
# ---------------------------------------------------------------------------

class AuthenticatedUser:
    """
    Lightweight container for the verified user identity.
    Passed into every protected route via Depends(get_current_user).
    """
    def __init__(self, user_id: str, phone: Optional[str] = None, username: Optional[str] = None):
        self.user_id = user_id
        self.phone = phone
        self.username = username

    def __repr__(self) -> str:
        return f"AuthenticatedUser(user_id={self.user_id}, username={self.username})"


# ---------------------------------------------------------------------------
# JWT verification helper (BUG-003 fix)
# ---------------------------------------------------------------------------

def _verify_yuvaa_jwt(token: str) -> Optional[AuthenticatedUser]:
    """
    Verify a YUVAA-issued HS256 JWT token.
    Returns AuthenticatedUser on success, None on failure.
    """
    try:
        import jwt
        payload = jwt.decode(
            token,
            settings.jwt_secret,
            algorithms=[settings.jwt_algorithm],
            options={"verify_exp": True}
        )
        user_id = payload.get("sub")
        username = payload.get("username")
        if not user_id:
            return None
        return AuthenticatedUser(user_id=user_id, username=username)
    except Exception:
        return None


# ---------------------------------------------------------------------------
# Core authentication dependency
# ---------------------------------------------------------------------------

async def get_current_user(
    authorization: Optional[str] = Header(default=None),
    x_dev_user_id: Optional[str] = Header(default=None),
) -> AuthenticatedUser:
    """
    FastAPI dependency: validates the caller's identity.

    Priority order:
      1. Dev bypass  (DEV_BYPASS_AUTH=true + X-Dev-User-Id header)
      2. YUVAA HS256 JWT   (generated by auth.py _create_access_token)
      3. Supabase JWT      (for users coming via real Supabase OTP flow)

    Raises:
      HTTP 401 if no valid token is provided.
      HTTP 401 if token validation fails at all levels.
    """
    # -----------------------------------------------------------------------
    # 1. Dev bypass — only active when explicitly configured
    # -----------------------------------------------------------------------
    dev_bypass = os.environ.get("DEV_BYPASS_AUTH", "false").lower() == "true"
    if dev_bypass:
        if x_dev_user_id:
            logger.debug("[DEV BYPASS] Accepting X-Dev-User-Id: %s", x_dev_user_id)
            return AuthenticatedUser(user_id=x_dev_user_id)
        if authorization and "dev-" in authorization:
            return AuthenticatedUser(user_id="00000000-0000-0000-0000-000000000001")

    # -----------------------------------------------------------------------
    # 2. Token must be present
    # -----------------------------------------------------------------------
    if not authorization:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Missing Authorization header. Expected: 'Bearer <token>'",
            headers={"WWW-Authenticate": "Bearer"},
        )

    parts = authorization.split(" ")
    if len(parts) != 2 or parts[0].lower() != "bearer":
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid Authorization header format. Expected: 'Bearer <token>'",
            headers={"WWW-Authenticate": "Bearer"},
        )

    token = parts[1]

    # -----------------------------------------------------------------------
    # 3. Try YUVAA HS256 JWT first (BUG-003 fix — primary path)
    # -----------------------------------------------------------------------
    yuvaa_user = _verify_yuvaa_jwt(token)
    if yuvaa_user:
        logger.debug("[JWT AUTH] Verified YUVAA JWT for user %s", yuvaa_user.user_id)
        return yuvaa_user

    # -----------------------------------------------------------------------
    # 4. Fallback: try Supabase JWT (for OTP-authenticated users)
    # -----------------------------------------------------------------------
    try:
        response = supabase.auth.get_user(token)
        if response and response.user:
            user = response.user
            logger.debug("[SUPABASE AUTH] Verified Supabase JWT for user %s", user.id)
            return AuthenticatedUser(
                user_id=str(user.id),
                phone=getattr(user, "phone", None)
            )
    except Exception as e:
        logger.debug("[SUPABASE AUTH] Supabase token validation failed: %s", e)

    # -----------------------------------------------------------------------
    # 5. All auth paths exhausted
    # -----------------------------------------------------------------------
    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Invalid or expired token. Please log in again.",
        headers={"WWW-Authenticate": "Bearer"},
    )
